89	/**
90	 * Finds the static directory containing the web app.
91	 *
92	 * When running in development (tsx), getDirectory() returns src/ and the app is at src/app/.
93	 * When bundled into dist/src/server/index.js, getDirectory() returns dist/src/server/
94	 * but the app is at dist/src/app/, so we need to check the parent directory.
95	 */
96	export function findStaticDir(): string {
97	  const baseDir = getDirectory();
98	
99	  // Try the standard location first (works in development)
100	  const standardPath = path.join(baseDir, 'app');
101	  if (fs.existsSync(path.join(standardPath, 'index.html'))) {
102	    return standardPath;
103	  }
104	
105	  // When bundled, the server is at dist/src/server/ but app is at dist/src/app/
106	  const parentPath = path.resolve(baseDir, '..', 'app');
107	  if (fs.existsSync(path.join(parentPath, 'index.html'))) {
108	    logger.debug(`Static directory resolved to parent: ${parentPath}`);
109	    return parentPath;
110	  }
111	
112	  // Fall back to standard path even if it doesn't exist (will fail gracefully later)
113	  logger.warn(`Static directory not found at ${standardPath} or ${parentPath}`);
114	  return standardPath;
115	}
