// GET /health
export const HealthResponseSchema = z.object({
  status: z.literal('OK'),
  version: z.string().min(1),
});

// GET /api/remote-health
export const RemoteHealthResponseSchema = z.object({
  status: z.string(),
  message: z.string(),
});

// GET /api/results
export const ResultsQuerySchema = z.object({
  datasetId: z.string().optional(),
  type: z.enum(['redteam', 'eval']).optional(),
  // Only the exact string 'true' coerces to boolean true; everything else
  // (including 'false', '1', 'yes', and omitted) resolves to false.
  includeProviders: z
    .string()
    .optional()
    .transform((value) => value === 'true'),
});

export type ResultsQuery = z.infer<typeof ResultsQuerySchema>;

// GET /api/prompts/:sha256hash
export const PromptsHashParamsSchema = z.object({
  sha256hash: z.string().regex(/^[a-f0-9]{64}$/i, 'must be a 64-character sha256hash'),
});

// GET /api/history
export const HistoryQuerySchema = z.object({
  tagName: z.string().optional(),
  tagValue: z.string().optional(),
  description: z.string().optional(),
});

// GET /api/results/share/check-domain
export const CheckDomainQuerySchema = z.object({
  id: z.string().min(1),
});

export const CheckDomainResponseSchema = z.object({
  domain: z.string(),
  isCloudEnabled: z.boolean(),
});

// POST /api/results/share
export const ShareRequestSchema = z.object({
  id: z.string().min(1),
});

export const ShareResponseSchema = z.object({
  url: z.string(),
});

// POST /api/dataset/generate
//
// String prompts are normalized to `{ raw, label }` objects (label defaults to
// the raw string). Object prompts preserve any extra fields, and a missing
// `label` defaults to the value of `raw`.
const PromptDtoSchema = z
  .union([z.string(), z.object({ raw: z.string() }).passthrough()])
  .transform((prompt) =>
    typeof prompt === 'string'
      ? { raw: prompt, label: prompt }
      : { ...prompt, label: (prompt.label as string | undefined) ?? prompt.raw },
  );

export const DatasetGenerateRequestSchema = z.object({
  prompts: z.array(PromptDtoSchema).min(1),
  tests: z
    .array(z.object({}).passthrough())
    .optional()
    .transform((tests) => tests ?? []),
});

export type DatasetGenerateRequest = z.infer<typeof DatasetGenerateRequestSchema>;

// POST /api/telemetry
export const TelemetryRequestSchema = TelemetryEventSchema;

