  History: { Query: HistoryQuerySchema },
  CheckDomain: { Query: CheckDomainQuerySchema, Response: CheckDomainResponseSchema },
  Share: { Request: ShareRequestSchema, Response: ShareResponseSchema },
  DatasetGenerate: { Request: DatasetGenerateRequestSchema },
  Telemetry: { Request: TelemetryRequestSchema },
} as const;
